import { useState } from 'react'

export function useUndoState(initial) {
  const [s, setS] = useState({ past: [], value: initial })
  return {
    value: s.value,
    canUndo: s.past.length > 0,
    set: (v) => setS((p) => ({ past: [...p.past, p.value], value: v })),
    undo: () => setS((p) => (p.past.length ? { past: p.past.slice(0, -1), value: p.past.at(-1) } : p)),
  }
}

