export function cartReducer(state, action) {
  switch (action.type) {
    case 'add': {
      const found = state.items.find((i) => i.id === action.item.id)
      if (found) return { items: state.items.map((i) => (i.id === found.id ? { ...i, qty: i.qty + 1 } : i)) }
      return { items: [...state.items, { ...action.item, qty: 1 }] }
    }
    case 'remove':
      return { items: state.items.filter((i) => i.id !== action.id) }
    case 'setQty':
      return { items: state.items.map((i) => (i.id === action.id ? { ...i, qty: action.qty } : i)).filter((i) => i.qty > 0) }
    case 'clear':
      return { items: [] }
    default:
      return state
  }
}

export function cartTotal(state) {
  return state.items.reduce((s, i) => s + i.price * i.qty, 0)
}

