import { expect, test } from 'vitest'
import { cartReducer, cartTotal } from './cartReducer'

const a = { id: 'a', price: 10 }

test('add twice increases qty', () => {
  const s = [{ type: 'add', item: a }, { type: 'add', item: a }].reduce(cartReducer, { items: [] })
  expect(s.items).toEqual([{ id: 'a', price: 10, qty: 2 }])
  expect(cartTotal(s)).toBe(20)
})

test('setQty 0 removes; remove and clear work', () => {
  let s = cartReducer({ items: [] }, { type: 'add', item: a })
  s = cartReducer(s, { type: 'add', item: { id: 'b', price: 5 } })
  expect(cartReducer(s, { type: 'setQty', id: 'a', qty: 0 }).items.map((i) => i.id)).toEqual(['b'])
  expect(cartReducer(s, { type: 'remove', id: 'b' }).items.map((i) => i.id)).toEqual(['a'])
  expect(cartReducer(s, { type: 'clear' }).items).toEqual([])
})

test('pure: never mutates, unknown actions return the same state', () => {
  const s = Object.freeze({ items: Object.freeze([Object.freeze({ id: 'a', price: 10, qty: 1 })]) })
  expect(() => cartReducer(s, { type: 'add', item: a })).not.toThrow()
  expect(cartReducer(s, { type: 'nope' })).toBe(s)
})

